add_filter( 'the_content', 'perfectpixel_author_bio_after_post', 40 );

function perfectpixel_author_bio_after_post( $content ) {
	if ( ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() ) {
		return $content;
	}
	$author_id = (int) get_post_field( 'post_author', get_the_ID() );
	$bio       = get_the_author_meta( 'description', $author_id );
	if ( '' === trim( (string) $bio ) ) {
		return $content;
	}
	$box  = '<aside class="perfectpixel-author-bio" style="display:flex;gap:1em;align-items:flex-start;margin-top:2em;padding:1.25em;border:1px solid rgba(0,0,0,.1);border-radius:6px">';
	$box .= get_avatar( $author_id, 72 );
	$box .= '<div><strong>' . esc_html( get_the_author_meta( 'display_name', $author_id ) ) . '</strong>';
	$box .= wpautop( wp_kses_post( $bio ) );
	$box .= '<a href="' . esc_url( get_author_posts_url( $author_id ) ) . '">' . esc_html( '{{author_bio_more}}' ) . '</a></div></aside>';
	return $content . $box;
}
